// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type FallingIntoPlaceProps = Record<string, any>;

const Bar: React.FC<{
  index: number;
  width: number;
  height: number;
  color: string;
  glow: string;
  rotation: number;
  isReflection?: boolean;
}> = ({ width, height, color, glow, rotation, isReflection = false }) => {
  const glowStyle = isReflection
    ? {}
    : {
        // Updated to provide a much stronger, layered glow effect
        boxShadow: `0 0 15px ${glow}, 0 0 30px ${glow}, 0 0 45px ${glow}80`,
        border: `2px solid ${color}`,
      };

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: `${color}10`, // Slight fill transparency
        borderRadius: 4,
        ...glowStyle,
        transform: `rotate(${rotation}deg)`,
        transformOrigin: "bottom right", // Updated to bottom-right for accurate physics pivot
        willChange: "transform",
      }}
    />
  );
};

const FallingIntoPlace: React.FC<FallingIntoPlaceProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "EVERYTHING WILL FALL INTO PLACE",
  barColor = "#ffffff",
  glowColor = "#ffffff",
  barCount = 7,
  barWidth = 60,
  barHeight = 300,
  gap = 40,
  initialTilt = 35,
  reflectionOpacity = 0.2,
}) => {
  useFontLoader(["Montserrat"]);
  
  const frame = useCurrentFrame();
  const { fps, width: videoWidth, height: videoHeight } = useVideoConfig();

  // Background Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate Layout
  const totalWidth = barCount * barWidth + (barCount - 1) * gap;
  const startX = (videoWidth - totalWidth) / 2;
  const bottomY = videoHeight * 0.65; // Position where bars sit

  // Dynamic Delay Calculation: Determine frame when bar hits the next one
  const hitDelay = useMemo(() => {
    // Calculate angle where top corner of current bar touches the next bar
    // With bottom-right pivot, the math is sin(theta) = gap / height
    const ratio = Math.min(gap / barHeight, 1);
    const hitAngle = Math.asin(ratio) * (180 / Math.PI);
    
    // Fraction of the tilt required to hit
    const progressNeeded = hitAngle / initialTilt;

    // If never hits (tilt too small or gap too big), return a default safety delay
    if (progressNeeded >= 1 || progressNeeded <= 0) return 15;

    // Find the exact frame where the spring animation crosses the collision threshold
    for (let f = 0; f < 120; f++) {
      const val = spring({
        frame: f,
        fps,
        config: { damping: 14, stiffness: 80, mass: 1.2 },
      });
      if (val >= progressNeeded) return f;
    }
    return 15; // Fallback
  }, [gap, barHeight, initialTilt, fps]);

  // Text Animation
  const textOpacity = interpolate(frame, [0, 60], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const textY = interpolate(frame, [0, 60], [20, 0], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Montserrat, sans-serif",
        overflow: "hidden",
      }}
    >
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: "15%",
          width: "100%",
          textAlign: "center",
          color: barColor,
          fontSize: 42,
          fontWeight: 300,
          letterSpacing: "0.15em",
          opacity: textOpacity,
          transform: `translateY(${textY}px)`,
          textShadow: `0 0 15px ${glowColor}80`,
          zIndex: 10,
        }}
      >
        {titleText}
      </div>

      {/* Main Bars Container */}
      <div
        style={{
          position: "absolute",
          left: startX,
          top: bottomY - barHeight,
          width: totalWidth,
          height: barHeight,
          display: "flex",
          gap,
          alignItems: "flex-end", // Align bottoms
          perspective: 1000, // Subtle perspective
        }}
      >
        {Array.from({ length: barCount }).map((_, i) => {
          const isLast = i === barCount - 1;
          const delay = i * hitDelay + 15; // Initial buffer + physics based stagger
          
          // Spring for the "straightening" effect
          const spr = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 14,    // Controlled bounce
              stiffness: 80,  // Soft spring
              mass: 1.2,      // Slightly heavy feel
            },
          });

          // Physics: Last block falls flat (90deg), others lean on each other
          const targetRotation = isLast ? 90 : initialTilt;
          
          // Interpolate rotation
          const rawRotation = interpolate(spr, [0, 1], [0, targetRotation]);
          
          // Clamp the last bar to 90 so it doesn't clip through the "floor" due to spring overshoot
          const rotation = isLast ? Math.min(rawRotation, 90) : rawRotation;

          return (
            <Bar
              key={`bar-${i}`}
              index={i}
              width={barWidth}
              height={barHeight}
              color={barColor}
              glow={glowColor}
              rotation={rotation}
            />
          );
        })}
      </div>

      {/* Reflection Container */}
      <div
        style={{
          position: "absolute",
          left: startX,
          top: bottomY, // Starts exactly where main bars end
          width: totalWidth,
          height: barHeight,
          display: "flex",
          gap,
          alignItems: "flex-start", // Align tops (which are visually bottoms due to flip)
          opacity: reflectionOpacity,
          transform: "scaleY(-1)", // Flip vertically
          maskImage: "linear-gradient(to bottom, white 0%, transparent 60%)",
          WebkitMaskImage: "linear-gradient(to bottom, white 0%, transparent 60%)",
          pointerEvents: "none",
        }}
      >
        {Array.from({ length: barCount }).map((_, i) => {
          const isLast = i === barCount - 1;
          const delay = i * hitDelay + 15;
          
          const spr = spring({
            frame: frame - delay,
            fps,
            config: { damping: 14, stiffness: 80, mass: 1.2 },
          });

          const targetRotation = isLast ? 90 : initialTilt;
          const rawRotation = interpolate(spr, [0, 1], [0, targetRotation]);
          const rotation = isLast ? Math.min(rawRotation, 90) : rawRotation;

          return (
            <Bar
              key={`reflect-${i}`}
              index={i}
              width={barWidth}
              height={barHeight}
              color={barColor}
              glow={glowColor}
              rotation={rotation}
              isReflection
            />
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default FallingIntoPlace;